params.fn:
function(ctx){
  var anchors=Array.from(document.querySelectorAll('a[href*="/video/"], a[href*="/note/"]'));
  var seen={};var out=[];var limit=Number(ctx.limit)||10;
  for(var i=0;i<anchors.length&&out.length<limit;i++){
    var a=anchors[i];
    var href=a.href||a.getAttribute('href')||'';
    var match=href.match(/\/(video|note)\/(\d+)/);
    if(!match)continue;
    if(seen[href])continue;
    seen[href]=1;
    var card=a.closest('li, article, section, div')||a;
    var text=((card&&card.innerText)||a.innerText||'').trim();
    var lines=text.split(/\n/).map(function(x){return x.trim();}).filter(Boolean);
    var authorLine=lines.find(function(x){return x.indexOf('@')===0;})||'';
    var duration=lines.find(function(x){return /^\d{1,2}:\d{2}(:\d{2})?$/.test(x);})||'';
    var interaction=lines.find(function(x){
      var plain=x.replace(/,/g,'');
      return /^\d+(\.\d+)?[万亿]?\+?$/.test(plain)&&plain.length>1;
    })||'';
    var title=lines.find(function(x){
      var plain=x.replace(/,/g,'');
      return x&&x.indexOf('@')!==0&&x!=='合集'
        &&!/^\d{1,2}:\d{2}(:\d{2})?$/.test(x)
        &&!/^\d+(\.\d+)?[万亿]?\+?$/.test(plain);
    })||'';
    var img=card.querySelector('img');
    out.push({
      kind:match[1],
      video_id:match[2],
      url:href.indexOf('//')===0?('https:'+href):href,
      title:title.slice(0,120),
      author:authorLine.replace(/^@/,''),
      duration:duration,
      interaction_text:interaction,
      cover:img?(img.src||''):'',
      summary:text.slice(0,300)
    });
  }
  return {keyword:String(ctx.keyword||''),count:out.length,videos:out};
}
